namespace Tripous.Data;

/// <summary>
/// Indicates how a provider generates integer row identifiers.
/// </summary>
public enum OidMode
{
    /// <summary>
    /// No integer identifier generation mode is specified.
    /// </summary>
    None,
    /// <summary>
    /// An identifier is obtained from a generator or sequence before insertion.
    /// </summary>
    Generator,
    /// <summary>
    /// An identifier is generated by an auto-increment column during insertion.
    /// </summary>
    AutoInc,
}
